{"file_path":"src/parser.js","content":"export class ParseError extends Error {
  constructor(message) {
    super(message)
    this.line = 0
  }
}

const fail = (m) => {
  throw new ParseError(m)
}

const newTable = () => ({ t: 'table', m: new Map(), header: false })
const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

class LineParser {
  constructor(s) {
    this.s = s
    this.i = 0
  }
  get c() {
    return this.s[this.i]
  }
  ws() {
    while (isWs(this.c)) this.i++
  }
  atEnd() {
    const c = this.c
    return c === undefined || c === '#' || c === ';'
  }
  basic() {
    // at opening quote
    this.i++
    let out = ''
    for (;;) {
      const c = this.c
      if (c === undefined) fail('unterminated string')
      this.i++
      if (c === '"') return out
      if (c !== '\\') {
        out += c
        continue
      }
      const e = this.c
      if (e === undefined) fail('unterminated string')
      this.i++
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(map, e)) out += map[e]
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else fail('invalid escape \\' + String.fromCodePoint(this.s.codePointAt(this.i - 1)))
    }
  }
  literal() {
    const j = this.s.indexOf("'", this.i + 1)
    if (j < 0) fail('unterminated string')
    const out = this.s.slice(this.i + 1, j)
    this.i = j + 1
    return out
  }
  name() {
    const c = this.c
    if (c === '"') return this.basic()
    if (c === "'") return this.literal()
    if (!isBare(c)) fail('expected a name')
    const st = this.i
    while (isBare(this.c)) this.i++
    return this.s.slice(st, this.i)
  }
  dotted() {
    const parts = [this.name()]
    for (;;) {
      const save = this.i
      this.ws()
      if (this.c === '.') {
        this.i++
        this.ws()
        parts.push(this.name())
      } else {
        this.i = save
        return parts
      }
    }
  }
  value(base) {
    this.ws()
    const c = this.c
    if (c === undefined || c === ',' || c === ']' || c === '}' || c === '#' || c === ';') fail('expected a value')
    if (c === '"') return { t: 'string', v: this.basic() }
    if (c === "'") return { t: 'string', v: this.literal() }
    if (c === '[') return this.array(base)
    if (c === '{') return this.inline(base)
    const st = this.i
    while (this.c !== undefined && !isWs(this.c) && this.c !== ',' && this.c !== ']' && this.c !== '}') this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    const d = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${d}$`).test(w)) return { t: 'integer', v: BigInt(w.replace(/_/g, '')) }
    if (new RegExp(`^[+-]?${d}(?:\\.${d}(?:[eE][+-]?${d})?|[eE][+-]?${d})$`).test(w))
      return { t: 'float', v: Number(w.replace(/_/g, '')) }
    return fail('invalid value ' + w)
  }
  array(base) {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.c === undefined || this.c === '#' || this.c === ';') fail('unterminated array')
      if (this.c === ']') {
        if (items.length === 0 || this.afterComma) {
          this.i++
          return { t: 'array', items, aot: false }
        }
      }
      this.afterComma = false
      items.push(this.value(base))
      this.ws()
      if (this.c === ',') {
        this.i++
        this.afterComma = true
        continue
      }
      if (this.c === ']') {
        this.i++
        return { t: 'array', items, aot: false }
      }
      fail('unterminated array')
    }
  }
  inline(base) {
    this.i++
    const tbl = newTable()
    this.ws()
    if (this.c === '}') {
      this.i++
      return tbl
    }
    for (;;) {
      this.ws()
      if (this.c === undefined || this.c === '#' || this.c === ';') fail('unterminated inline table')
      const key = this.dotted()
      this.ws()
      if (this.c !== '=') fail('expected = in an inline table')
      this.i++
      const val = this.value([...base, ...key])
      assign(tbl, base, key, val)
      this.ws()
      if (this.c === ',') {
        this.i++
        continue
      }
      if (this.c === '}') {
        this.i++
        return tbl
      }
      fail('unterminated inline table')
    }
  }
}

function step(cur, key, path) {
  // walk into an existing child that must be a table or array of tables
  const n = cur.m.get(key)
  if (n.t === 'table') return n
  if (n.t === 'array' && n.aot) return n.items[n.items.length - 1]
  return fail(path.join('.') + ' is not a table')
}

function assign(tbl, base, key, val) {
  // base is the path of tbl; key is relative
  let cur = tbl
  for (let k = 0; k < key.length - 1; k++) {
    const p = [...base, ...key.slice(0, k + 1)]
    if (cur.m.has(key[k])) cur = step(cur, key[k], p)
    else {
      const t = newTable()
      cur.m.set(key[k], t)
      cur = t
    }
  }
  const last = key[key.length - 1]
  if (cur.m.has(last)) fail('key ' + [...base, ...key].join('.') + ' is defined twice')
  cur.m.set(last, val)
}

function parseLine(root, state, s) {
  const first = s.search(/[^ \t]/)
  if (first < 0 || s[first] === '#' || s[first] === ';') return
  const p = new LineParser(s)
  p.ws()
  if (p.c === '[') {
    p.i++
    const isArr = p.c === '['
    if (isArr) p.i++
    p.ws()
    const key = p.dotted()
    p.ws()
    const close = isArr ? ']]' : ']'
    if (s.slice(p.i, p.i + close.length) !== close) fail('unterminated table header')
    p.i += close.length
    p.ws()
    if (!p.atEnd()) fail('trailing text after a table header')
    let cur = root
    for (let k = 0; k < key.length - 1; k++) {
      if (cur.m.has(key[k])) cur = step(cur, key[k], key.slice(0, k + 1))
      else {
        const t = newTable()
        cur.m.set(key[k], t)
        cur = t
      }
    }
    const last = key[key.length - 1]
    const path = key.join('.')
    const ex = cur.m.get(last)
    if (isArr) {
      if (!ex) {
        const t = newTable()
        cur.m.set(last, { t: 'array', items: [t], aot: true })
        state.cur = t
      } else if (ex.t === 'array' && ex.aot) {
        const t = newTable()
        ex.items.push(t)
        state.cur = t
      } else fail(path + ' is not an array of tables')
    } else if (!ex) {
      const t = newTable()
      t.header = true
      cur.m.set(last, t)
      state.cur = t
    } else if (ex.t !== 'table') fail(path + ' is not a table')
    else if (ex.header) fail('table ' + path + ' is defined twice')
    else {
      ex.header = true
      state.cur = ex
    }
    return
  }
  const key = p.dotted()
  p.ws()
  if (p.c !== '=') fail('expected key = value')
  p.i++
  const val = p.value(state.path.concat(key))
  p.ws()
  if (!p.atEnd()) fail('trailing text after a value')
  assign(state.cur, state.path, key, val)
}

export function parseDocument(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = newTable()
  const state = { cur: root, path: [] }
  lines.forEach((raw, idx) => {
    const line = raw.endsWith('\r') ? raw.slice(0, -1) : raw
    try {
      parseLine(root, state, line)
    } catch (e) {
      if (e instanceof ParseError) e.line = idx + 1
      throw e
    }
  })
  return root
}
"}

